// Forward a private message to the team group. A stranger's text is shown, so nothing in it can ping people or break the layout.
const MAX_PER_PERSON = 5;
const MAX_ALL = 20;
const clean = (text) => String(text).replace(/@(?=\d)/g, '@\u200b').replace(/[\r\n]+/g, ' ');

const event = msg.payload;
if (event.type !== 'message.received') {
    return null;
}
const data = event.data || {};
const sender = data.from || {};
if ((data.to && data.to.group_id) || !sender.number) {
    return null;
}
// At most MAX_PER_PERSON forwards an hour from one person and MAX_ALL in all: a flood cannot fill the group or use up your allowance.
const nowMs = event.created_at ? new Date(event.created_at).getTime() : Date.now();
const forwarded = flow.get('forwarded') || {};
const mine = (forwarded[sender.number] || []).filter((t) => t > nowMs - 3600 * 1000);
const all = (flow.get('forwardedAll') || []).filter((t) => t > nowMs - 3600 * 1000);
if (mine.length >= MAX_PER_PERSON || all.length >= MAX_ALL) {
    return null;
}
mine.push(nowMs);
all.push(nowMs);
forwarded[sender.number] = mine;
flow.set('forwarded', forwarded);
flow.set('forwardedAll', all);
const who = (sender.name ? clean(sender.name) + ' ' : '') + '(+' + sender.number + ')';
msg.to = 'grp_0198d3c5a1b24d3e9f01a2b3c4d5e6f7'; // replace with the id of your team group
msg.number = event.number_alias || 'main';
msg.payload = 'New message from ' + who + ': ' + clean(data.preview || '[' + data.content_type + ']');
return msg;
